pub fn count_routes(locations: Vec<i32>, start: i32, finish: i32, fuel: i32) -> i32 {
    let n = locations.len();
    let MOD: i64 = 1_000_000_007;
    let start_pos = locations[start as usize] as i64;
    let finish_pos = locations[finish as usize] as i64;

    fn solve(
        current_city: usize,
        remaining_fuel: i64,
        locations: &Vec<i32>,
        finish_city: usize,
        modulo: i64,
    ) -> i64 {
        if current_city == finish_city {
            if remaining_fuel >= 0 {
                return 1;
            } else {
                return 0;
            }
        }

        let mut count: i64 = 0;
        for next_city in 0..locations.len() {
            if next_city != current_city {
                let cost = (locations[current_city] as i64 - locations[next_city] as i64).abs();
                if remaining_fuel >= cost {
                    count = (count + solve(next_city, remaining_fuel - cost, locations, finish_city, modulo)) % modulo;
                }
            }
        }
        count
    }

    solve(
        start as usize,
        fuel as i64,
        &locations,
        finish as usize,
        MOD,
    ) as i32
}
